{"content":""""Independent check of summary.csv against the raw logs.

Recomputes expected counts with a different code path (regex token scan,
per-period file selection) and compares to the produced CSV.
Exits non-zero on any mismatch.
"""

import csv
import re
import sys
from datetime import date, timedelta
from pathlib import Path

BASE = Path(__file__).resolve().parent
SEV_RE = re.compile(r"\b(ERROR|WARNING|INFO)\b")
NAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")
EXPECTED_ORDER = [
    (p, s)
    for p in ["today", "last_7_days", "last_30_days", "month_to_date", "total"]
    for s in ["ERROR", "WARNING", "INFO"]
]


def main() -> int:
    ref = date.fromisoformat((BASE / "reference_date.txt").read_text(encoding="utf-8").strip())

    per_file = {}
    for path in sorted((BASE / "logs").glob("*.log")):
        m = NAME_RE.match(path.name)
        if not m:
            continue
        d = date.fromisoformat(m.group(1))
        counts = {"ERROR": 0, "WARNING": 0, "INFO": 0}
        for line in path.read_text(encoding="utf-8").splitlines():
            found = SEV_RE.findall(line)
            if len(found) != 1:
                print(f"FAIL: line without exactly one severity in {path.name}: {line!r}")
                return 1
            counts[found[0]] += 1
        per_file[d] = counts

    def window(lo, hi):
        agg = {"ERROR": 0, "WARNING": 0, "INFO": 0}
        for d, c in per_file.items():
            if lo <= d <= hi:
                for s in agg:
                    agg[s] += c[s]
        return agg

    expected = {
        "today": window(ref, ref),
        "last_7_days": window(ref - timedelta(days=6), ref),
        "last_30_days": window(ref - timedelta(days=29), ref),
        "month_to_date": window(ref.replace(day=1), ref),
        "total": window(date.min, date.max),
    }

    rows = list(csv.reader((BASE / "summary.csv").read_text(encoding="utf-8").splitlines()))
    if not rows or rows[0] != ["period", "severity", "count"]:
        print(f"FAIL: bad header {rows[0] if rows else None}")
        return 1
    body = rows[1:]
    if len(body) != 15:
        print(f"FAIL: expected 15 data rows, got {len(body)}")
        return 1

    ok = True
    for (period, sev), row in zip(EXPECTED_ORDER, body):
        if row[0] != period or row[1] != sev:
            print(f"FAIL: row order mismatch: expected {period},{sev} got {row[0]},{row[1]}")
            ok = False
            continue
        want = expected[period][sev]
        if int(row[2]) != want:
            print(f"FAIL: {period},{sev} expected {want} got {row[2]}")
            ok = False

    if not ok:
        return 1
    print("PASS: summary.csv matches independently recomputed counts")
    for period in expected:
        print(f"  {period}: {expected[period]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
